def is_balanced(sequence):
    stack = []
    for num in sequence:
        if num > 0:
            stack.append(num)
        else:
            if stack and stack[-1] == -num:
                stack.pop()
            else:
                return False
    return not stack

def can_order_cards(n, cards):
    front_sequence = []
    back_sequence = []
    for card in cards:
        front_sequence.append(card[0])
        back_sequence.append(card[1])

